package main

import (
	"fmt"
	"slices"
	"strings"

	"ofam.dev/matomeru/internal/notices"
	"ofam.dev/ochazuke"
)

// The license noun is the third-party notices embedded in this binary
// (internal/notices, generated by make licenses): every module the build
// links, its licences, and the licence and notice files that go with it.
// A nodaemon build lists fewer modules (daemonBuilt).

// licenseRow is one linked module: license.all.
type licenseRow struct {
	Module   string   `json:"module"`
	Version  string   `json:"version,omitempty"`
	Licenses []string `json:"licenses"`
	Files    []string `json:"files"`
	Daemon   bool     `json:"daemon,omitempty"` // linked only with the daemon built in
}

var licenseColumns = []ochazuke.Column{
	{Title: "module", Min: 20},
	{Title: "version", Priority: 2},
	{Title: "licenses", Priority: 1},
}

func (a *App) defineLicense() {
	n := a.r.Define("license").Columns(licenseColumns...).
		About("The third-party licences in this build: every linked module and the notices that must travel with it")
	a.localVerb(n, "license", "all", a.licenseAll, "List every module this build links with its licences (the daemon's modules only when the daemon is built in)").Fetch()
	a.localVerb(n, "license", "show", a.licenseShow, "Print the licence and notice texts of one module, or of every module when none is given").Fetch()
	a.parameters("license.show", map[string]ochazuke.Parameter{
		"module": {Type: "string", Description: "A module path (or a prefix of one); omit for all of them"},
	})
	op := a.r.Operations.At(ochazuke.Key(a.r.CanonicalKey("license.show")))
	op.Positional = []string{"module"}
	a.r.Operations.Set(op)
}

// linkedNotices is the embedded data for this build.
func linkedNotices() ([]notices.Module, error) {
	ix, err := notices.Load()
	if err != nil {
		return nil, fmt.Errorf("licence data: %w", err)
	}
	return ix.Linked(daemonBuilt), nil
}

func moduleName(m notices.Module) string {
	if m.Std {
		return "Go standard library"
	}
	return m.Path
}

func (a *App) licenseAll(ochazuke.Ctx) ochazuke.Result {
	mods, err := linkedNotices()
	if err != nil {
		return ochazuke.Failed(err)
	}
	rows := make([]licenseRow, 0, len(mods))
	for _, m := range mods {
		r := licenseRow{Module: moduleName(m), Version: m.Version, Licenses: m.Licenses(), Daemon: m.DaemonOnly}
		for _, f := range m.Files {
			r.Files = append(r.Files, f.Name)
		}
		rows = append(rows, r)
	}
	return ochazuke.Done(rows)
}

// licenseShow prints each wanted module's files, each text once per module.
func (a *App) licenseShow(c ochazuke.Ctx) ochazuke.Result {
	mods, err := linkedNotices()
	if err != nil {
		return ochazuke.Failed(err)
	}
	want := ochazuke.StringArg(c.Args, "module", "")
	var b strings.Builder
	n := 0
	for _, m := range mods {
		if want != "" && !strings.HasPrefix(m.Path, want) && !strings.EqualFold(moduleName(m), want) {
			continue
		}
		n++
		head := moduleName(m)
		if m.Version != "" {
			head += " " + m.Version
		}
		fmt.Fprintf(&b, "%s\n%s\n", head, strings.Repeat("=", len(head)))
		for _, f := range m.Files {
			t, err := notices.Text(f.Text)
			if err != nil {
				return ochazuke.Failed(fmt.Errorf("%s %s: %w", m.Path, f.Name, err))
			}
			label := f.Name
			if len(f.SPDX) > 0 {
				s := slices.Clone(f.SPDX)
				label += " (" + strings.Join(s, ", ") + ")"
			}
			fmt.Fprintf(&b, "\n--- %s ---\n\n%s\n", label, strings.TrimRight(t, "\n"))
		}
		b.WriteString("\n")
	}
	if n == 0 {
		return ochazuke.Failed(fmt.Errorf("no linked module matches %q (license.all lists them)", want))
	}
	return ochazuke.Done(b.String())
}
